// Call the target function to obtain the version string pointer (constant, not owned by caller)
const char *version = w2l_shim_version();

// Enforce non-null contract for downstream usage
if (!version) { FUZZ_BAIL(); }

// Validate that the returned string is NUL-terminated within a bounded range to avoid unbounded reads
// This also implicitly checks basic pointer validity under sanitizers.
size_t max_check = 4096; // reasonable upper bound for a version string
size_t len = 0;
for (; len < max_check; ++len) {
    if (version[len] == '\0') { break; }
}
if (len == max_check) { FUZZ_BAIL(); }

// Optionally touch bytes to exercise read paths without modifying the buffer
// (Do not modify or free; caller does not own the memory.)
volatile unsigned char checksum = 0;
for (size_t i = 0; i < len; ++i) { checksum ^= (unsigned char)version[i]; }
(void)checksum;

// Record attributes on the pointer. Cast to void* for the attribute system's key type.
FUZZ_SET_ATTR_INT((void*)version, "ownership", 0);      // 0 => do not free/delete
FUZZ_SET_ATTR_STR((void*)version, "lifetime", "static");
FUZZ_SET_ATTR_INT((void*)version, "length", (int)len);

// Validation summary: ensures non-null, bounded NUL-termination, and records non-owning/static attributes for safe downstream use.
